INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(110963, 'ruRU', '', 'Время игр закончено, смертный!', 24330),
(110964, 'ruRU', '', '$n, это Фело''мелорн? ТОТ Фело''мелорн, неугасимое пламя Солнечных Скитальцев? В последний раз, когда я видел этот клинок, он был в руках принца Кель''таса, ещё до третьей войны.', 24330),
(110971, 'ruRU', '', 'На самом деле, сестра, игры только начинаются!', 24330),
(110980, 'ruRU', '', 'Калаззиус Коварный... Я слышал это имя. Он скрывается в пещере к востоку от долины! Встретимся там!', 24330),
(111003, 'ruRU', '', 'Эту дверь запирает демоническая руна! Эмпиреевскому Обществу не следует использовать такую магию!', 24330),
(111006, 'ruRU', '', 'Прекрасный вид отсюда. Хм, а вот эта книга заслуживает более внимательного взгляда.', 24330),
(111007, 'ruRU', '', 'Архимаг Варгот узнает об этом вторжении!', 24330),
(111017, 'ruRU', '', 'О нет! Равандвир!', 24330),
(111020, 'ruRU', '', 'Да, я знаю это кольцо. Я даже видел его, совсем недавно, ещё вчера.$b$bК сожалению, новости не самые хорошие. Оно было среди множества безделушек, украденных этими ужасными мурлоками. Мне удалось расправиться с несколькими из них на пути, но они утащили немало сокровищ... включая это кольцо.', 24330),
(111043, 'ruRU', '', 'Отойди оттуда!', 24330),
(111044, 'ruRU', '', 'Ты друг или враг, $r? Если считаешь себя другом леса, докажи это. Помоги отбросить порчу, что грозит захватить мой дом.', 24330),
(111045, 'ruRU', '', 'Благодарю тебя, $r. Ты доказал, что являешься истинным союзником. Желаю тебе сил в борьбе против зла этой земли.', 24330),
(111079, 'ruRU', '', 'Здесь ты найдёшь лишь смерть!', 24330),
(111080, 'ruRU', '', 'Беги сейчас же, и ты, возможно, ещё сохранишь свою хрупкую жизнь.', 24330),
(111081, 'ruRU', '', 'Да будет так. Тогда ты сгниёшь в этих залах.', 24330),
(111082, 'ruRU', '', 'Глупец! Ты не понимаешь, какие силы искушаешь!', 24330),
(111083, 'ruRU', '', 'Мой военачальник... у нас... гости...', 24330),
(111098, 'ruRU', '', 'Твой друг прав. Нам стоит действовать вместе.', 24330),
(111101, 'ruRU', '', 'Привет. Ты пришёл, чтобы присоединиться к Эмпиреевскому Обществу Экзотических Магических Искусств?', 24330),
(111114, 'ruRU', '', 'Так и сделаю. До скорой встречи, $n.', 24330),
(111115, 'ruRU', '', 'Я не стану сражаться с Пылающим Легионом, пока Молот Сумерек держит Подземье в осаде!', 24330),
(111117, 'ruRU', '', 'Иди. Уничтожь Молот Сумерек, и ты заслужишь мою благосклонность!', 24330),
(111151, 'ruRU', '', 'Пусть это останется между нами, $c. Как говорится, болтливый язык до беды доведёт.', 24330),
(111177, 'ruRU', '', 'Эти презренные создания оскверняют нашу священную землю, собирая души для своей проклятой королевы! Прикончи их!', 24330),
(111179, 'ruRU', '', 'Благодарю, защитник! Святость этого места сохранена благодаря твоей помощи.', 24330),
(111193, 'ruRU', '', 'Круг Земли оказал Подземью великую услугу. Мы отплатим добром.', 24330),
(111194, 'ruRU', '', 'Мать Камня всегда платит свои долги.', 24330),
(111195, 'ruRU', '', 'В знак нашего союза я подарю тебе одного из своих величайших воинов.', 24330),
(111196, 'ruRU', '', 'Защищай Круг Земли, Лавинион. Вымости землю трупами Пылающего Легиона!', 24330),
(111211, 'ruRU', '', 'Ага. Иди вперёд, милый. Мы скоро подойдём.', 24330),
(111235, 'ruRU', '', 'Ну, как ты знаешь, обследование местности может занять немало времени.$b$bНужно установить оборудование, что само по себе работа, затем изучить результаты и попытаться приблизиться к тому месту, где, по твоим предположениям, может находиться фрагмент.$b$bВсё, о чём я просил — что-нибудь, чтобы ускорить этот процесс. Но, видимо, моё объяснение нашего процесса оказалось для Налтаниса слишком сложным, чтобы его выслушать.$b$bМожет, ты объяснишь ему это лучше, чем я.', 24330),
(111236, 'ruRU', '', 'Не похож ты на любителя археологии. Видишь ли, обследование местности может занять немало времени.$b$bНужно установить оборудование, что само по себе работа, затем изучить результаты и попытаться приблизиться к тому месту, где, по твоим предположениям, может находиться фрагмент.$b$bВсё, о чём я просил — что-нибудь, чтобы ускорить этот процесс. Но, видимо, моё объяснение нашего процесса оказалось для Налтаниса слишком сложным, чтобы его выслушать.$b$bМожет, ты объяснишь ему это лучше, чем я.', 24330),
(111239, 'ruRU', '', 'Похоже, кто-то сам напрашивается! Дайте мне до них добраться!', 24330),
(111240, 'ruRU', '', 'Ты связался не с той девчонкой!', 24330),
(111241, 'ruRU', '', 'Сегодня явно не твой день!', 24330),
(111242, 'ruRU', '', 'Похоже, денёк будет долгим!', 24330),
(111243, 'ruRU', '', 'Долг зовёт!', 24330),
(111251, 'ruRU', '', 'Спасибо!', 24330),
(111279, 'ruRU', '', 'Это опасно?', 24330),
(111281, 'ruRU', '', 'Этот мир теперь принадлежит Азшаре, шаман. Как символично, что Круг Земли будет смыт морем!', 24330);
